#include <iostream>
#include <memory>
#include <string>

// Modern C++17 Binary Search Tree Node
struct TreeNode {
    int val;
    std::unique_ptr<TreeNode> left;
    std::unique_ptr<TreeNode> right;

    explicit TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}
};

// Helper to insert values into the BST
void insertBST(std::unique_ptr<TreeNode>& root, int val) {
    if (!root) {
        root = std::make_unique<TreeNode>(val);
        return;
    }
    if (val < root->val) {
        insertBST(root->left, val);
    } else {
        insertBST(root->right, val);
    }
}

// Textbook algorithm from Page 550:
// outputTree traverses right subtree, prints node with indentation, traverses left subtree
void outputTree(const TreeNode* node, int totalSpaces) {
    if (node == nullptr) {
        return;
    }

    // 1. Recursively call outputTree with right subtree and totalSpaces + 5
    outputTree(node->right.get(), totalSpaces + 5);

    // 2. Output spaces and current node value
    std::cout << std::string(totalSpaces, ' ') << node->val << "\n";

    // 3. Recursively call outputTree with left subtree and totalSpaces + 5
    outputTree(node->left.get(), totalSpaces + 5);
}

int main() {
    std::unique_ptr<TreeNode> root = nullptr;

    // Sample values demonstrating tree hierarchy
    int values[] = {49, 28, 83, 18, 40, 71, 97};
    for (int v : values) {
        insertBST(root, v);
    }

    std::cout << "Rotated 2D Binary Tree Display (Root at left):\n";
    outputTree(root.get(), 0);

    return 0;
}
